import{_ as t,o as a,c as o,a6 as n}from"./chunks/framework.4tsfTCyC.js";const h=JSON.parse('{"title":"Remote Agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/remote-agents.md","filePath":"guide/remote-agents.md"}'),i={name:"guide/remote-agents.md"};function r(s,e,l,c,u,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="remote-agents" tabindex="-1">Remote Agents <a class="header-anchor" href="#remote-agents" aria-label="Permalink to &quot;Remote Agents&quot;">​</a></h1><p>Remote agents are cloud-hosted AI agents maintained by the TeXRA team that extend your extension&#39;s capabilities with specialized functionality. They&#39;re automatically updated with the latest improvements and optimizations without requiring extension updates.</p><h2 id="what-are-remote-agents" tabindex="-1">What Are Remote Agents? <a class="header-anchor" href="#what-are-remote-agents" aria-label="Permalink to &quot;What Are Remote Agents?&quot;">​</a></h2><p>Remote agents are pre-configured AI assistants hosted in the cloud that you can access directly from TeXRA. Unlike built-in agents, they:</p><ul><li>Receive updates automatically without requiring extension updates</li><li>Provide specialized capabilities for specific research domains</li><li>Load on-demand to keep your extension lightweight</li></ul><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><h3 id="_1-sign-in-to-texra" tabindex="-1">1. Sign In to TeXRA <a class="header-anchor" href="#_1-sign-in-to-texra" aria-label="Permalink to &quot;1. Sign In to TeXRA&quot;">​</a></h3><p>To access remote agents, you need a TeXRA account:</p><ol><li>Open the Command Palette (<code>Ctrl+Shift+P</code> / <code>Cmd+Shift+P</code>)</li><li>Run the command: <strong>TeXRA: Sign In</strong></li><li>Choose your preferred sign-in method (GitHub, Google, or GitLab)</li><li>Complete the authentication flow in your browser</li><li>Return to VS Code once authenticated</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can check your authentication status anytime by running <strong>TeXRA: View Profile</strong> from the Command Palette.</p></div><h3 id="_2-browse-available-agents" tabindex="-1">2. Browse Available Agents <a class="header-anchor" href="#_2-browse-available-agents" aria-label="Permalink to &quot;2. Browse Available Agents&quot;">​</a></h3><p>Once signed in, you can explore remote agents from your profile:</p><ol><li>Open the Command Palette</li><li>Run: <strong>TeXRA: View Profile</strong></li><li>Browse the <strong>Remote Agents</strong> table showing all available agents</li><li>Click <strong>Use</strong> on any agent to add it to your agent selector</li></ol><p>The selected agent will appear in your main TeXRA view alongside your built-in agents.</p><h3 id="_3-use-remote-agents" tabindex="-1">3. Use Remote Agents <a class="header-anchor" href="#_3-use-remote-agents" aria-label="Permalink to &quot;3. Use Remote Agents&quot;">​</a></h3><p>Remote agents work just like built-in agents:</p><ol><li>Open the TeXRA view (click the TeXRA icon in the Activity Bar)</li><li>Select your remote agent from the agent dropdown</li><li>Choose your input file and model</li><li>Click <strong>Run</strong> to execute the agent</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Remote agents are marked with a cloud icon (☁️) in the agent selector to distinguish them from local agents.</p></div><h2 id="research-access-program" tabindex="-1">Research Access Program <a class="header-anchor" href="#research-access-program" aria-label="Permalink to &quot;Research Access Program&quot;">​</a></h2><p>The <strong>Research Access Program</strong> provides access to specialized remote agents designed for academic research and professional writing. Program members get access to:</p><ul><li><strong>Specialized domain agents</strong>: Agents tailored for specific research fields (mathematics, computer science, physics, etc.)</li><li><strong>Advanced reasoning capabilities</strong>: Multi-step analysis and complex document processing</li><li><strong>Beta features</strong>: Early access to experimental agents and capabilities</li><li><strong>Priority improvements</strong>: Your feedback directly influences agent development</li></ul><p>Different agents may be available to different research groups based on their domain and needs.</p><h3 id="joining-the-program" tabindex="-1">Joining the Program <a class="header-anchor" href="#joining-the-program" aria-label="Permalink to &quot;Joining the Program&quot;">​</a></h3><p>The Research Access Program is available to active researchers, academics, and technical writers. To join:</p><ol><li><strong>Sign in</strong> to TeXRA using your institutional or professional email</li><li><strong>Contact us</strong> at <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a> with: <ul><li>Your name and affiliation</li><li>Brief description of your research area</li><li>How you plan to use remote agents</li></ul></li></ol><p>We&#39;ll review your application and grant appropriate access within 1-2 business days.</p><div class="tip custom-block"><p class="custom-block-title">Free for Researchers</p><p>TeXRA is committed to supporting academic research. The Research Access Program is <strong>free for qualifying researchers and students</strong>. We do not charge for remote agent access.</p></div><h2 id="managing-your-account" tabindex="-1">Managing Your Account <a class="header-anchor" href="#managing-your-account" aria-label="Permalink to &quot;Managing Your Account&quot;">​</a></h2><h3 id="view-your-profile" tabindex="-1">View Your Profile <a class="header-anchor" href="#view-your-profile" aria-label="Permalink to &quot;View Your Profile&quot;">​</a></h3><p>Check your account status and available agents:</p><ol><li>Open Command Palette</li><li>Run: <strong>TeXRA: View Profile</strong></li><li>View your email, user ID, and access level</li><li>Browse remote agents available to you</li></ol><h3 id="sign-out" tabindex="-1">Sign Out <a class="header-anchor" href="#sign-out" aria-label="Permalink to &quot;Sign Out&quot;">​</a></h3><p>To sign out of your TeXRA account:</p><ol><li>Open Command Palette</li><li>Run: <strong>TeXRA: Sign Out</strong></li><li>Confirm sign out</li></ol><p>Your local agents will continue to work normally after signing out. You&#39;ll only lose access to remote agents until you sign in again.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="do-i-need-to-sign-in-to-use-texra" tabindex="-1">Do I need to sign in to use TeXRA? <a class="header-anchor" href="#do-i-need-to-sign-in-to-use-texra" aria-label="Permalink to &quot;Do I need to sign in to use TeXRA?&quot;">​</a></h3><p>No. TeXRA works fully offline with built-in agents. You only need to sign in if you want access to remote agents from the cloud.</p><h3 id="are-remote-agents-slower-than-built-in-agents" tabindex="-1">Are remote agents slower than built-in agents? <a class="header-anchor" href="#are-remote-agents-slower-than-built-in-agents" aria-label="Permalink to &quot;Are remote agents slower than built-in agents?&quot;">​</a></h3><p>Remote agents perform similarly to built-in agents. The agent configuration is loaded from the cloud, but the actual AI model execution happens using your configured API keys just like with built-in agents.</p><h3 id="can-i-use-remote-agents-offline" tabindex="-1">Can I use remote agents offline? <a class="header-anchor" href="#can-i-use-remote-agents-offline" aria-label="Permalink to &quot;Can I use remote agents offline?&quot;">​</a></h3><p>No. Remote agents require an internet connection to load their configurations. If you need offline access, use built-in agents instead.</p><h3 id="what-happens-to-my-documents" tabindex="-1">What happens to my documents? <a class="header-anchor" href="#what-happens-to-my-documents" aria-label="Permalink to &quot;What happens to my documents?&quot;">​</a></h3><p>Your documents are never uploaded to TeXRA servers. Remote agents only load their configuration (prompts and settings) from the cloud. All document processing happens locally using your own API keys.</p><h3 id="can-i-create-my-own-remote-agents" tabindex="-1">Can I create my own remote agents? <a class="header-anchor" href="#can-i-create-my-own-remote-agents" aria-label="Permalink to &quot;Can I create my own remote agents?&quot;">​</a></h3><p>Currently, remote agents are maintained by the TeXRA team. If you have ideas for new agents or want to share your custom agents with the community, contact us at <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a>.</p><h3 id="how-do-i-disable-remote-agents" tabindex="-1">How do I disable remote agents? <a class="header-anchor" href="#how-do-i-disable-remote-agents" aria-label="Permalink to &quot;How do I disable remote agents?&quot;">​</a></h3><p>If you prefer not to use remote agents:</p><ol><li>Open VS Code Settings (<code>Ctrl+,</code> / <code>Cmd+,</code>)</li><li>Search for: <code>texra.remoteAgents.enabled</code></li><li>Uncheck the setting</li></ol><p>This will hide remote agents from your interface without affecting built-in agents.</p><h2 id="need-help" tabindex="-1">Need Help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need Help?&quot;">​</a></h2><p>If you encounter any issues with remote agents or have questions about the Researcher Access Program:</p><ul><li><strong>Email</strong>: <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a></li><li><strong>Documentation</strong>: <a href="https://texra.ai/guide" target="_blank" rel="noreferrer">texra.ai/guide</a></li></ul><p>We typically respond to inquiries within 24-48 hours.</p>',54)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
